"""C619 recession-risk research backtest.

Paper: https://arxiv.org/abs/2603.07813
Research references (ideas only, independently implemented):
- AWRY (MIT): https://github.com/aditauqir/AWRY
  https://github.com/aditauqir/AWRY/blob/main/src/evaluation/walk_forward.py
- Recession-Nowcast (license unspecified): https://github.com/dmehndiratta/Recession-Nowcast
  https://github.com/dmehndiratta/Recession-Nowcast/blob/main/pipeline/03_analysis/backtest.py
- QuantConnect research example: https://www.quantconnect.com/docs/v1/research/alternative-data
- fredapi (PyPI): https://pypi.org/project/fredapi/
"""

from datetime import datetime
import gzip
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path

import numpy as np
import pandas as pd
from sklearn.linear_model import LogisticRegression
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from threadpoolctl import threadpool_limits
import yaml


ROOT = Path(__file__).resolve().parent


def read_config():
    config = yaml.safe_load((ROOT / "config.yaml").read_text(encoding="utf-8"))
    dates = {key: pd.Timestamp(value) for key, value in config["dates"].items()}
    start, first, split, end = (dates[key] for key in (
        "predictor_start", "backtest_start", "is_end", "backtest_end"
    ))
    if not start < first < split < end or not split.is_month_end:
        raise ValueError("Expected ordered dates and a month-end IS cutoff")
    availability = config["availability"]
    if (availability["treasury_calendar_days"] < 1
            or availability["recession_label_months"] < 24
            or availability["execution_sessions"] < 1):
        raise ValueError("Expected positive price and execution lags and a 24-month label embargo")
    model = config["model"]
    if model["horizon_months"] < 1 or min(model["feature_lags_months"]) < 0:
        raise ValueError("Forecast horizon must be positive and feature lags nonnegative")
    return config, dates


def snapshot_frame(snapshots, name):
    snapshot = snapshots[name]
    raw = gzip.decompress(snapshot["gzip"])
    digest = sha256(raw).hexdigest()
    if digest != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {name}")
    with BytesIO(raw) as file:
        fetched_at = datetime.fromisoformat(file.readline().decode("utf-8").strip())
        frame = pd.read_csv(file, index_col=0, parse_dates=True)
    body_digest = sha256(raw.partition(b"\n")[2]).hexdigest()
    return frame, fetched_at.isoformat(), digest, body_digest


def load_inputs(snapshots, universe, dates):
    start, end = dates["predictor_start"], dates["backtest_end"]
    etf_start = dates["backtest_start"] - pd.Timedelta(days=14)
    etfs = dict.fromkeys(universe[key] for key in ("risk_on", "risk_off", "benchmark"))
    indexes = dict.fromkeys(universe[key] for key in (
        "equity_index", "treasury_10y", "treasury_5y", "treasury_3m"
    ))
    loaded = {}
    hashes, body_hashes = {}, {}
    for tickers, first_date, kind in ((etfs, etf_start, "etf"), (indexes, start, "index")):
        for ticker in tickers:
            name = f"{kind}_{ticker}_{first_date.date()}_{end.date()}.csv"
            frame, timestamp, hashes[name], body_hashes[name] = snapshot_frame(snapshots, name)
            loaded[ticker] = (frame, timestamp)
    series = universe["recession_label"]
    name = f"fred_{series}_{start.date()}_{end.date()}.csv"
    labels, label_timestamp, hashes[name], body_hashes[name] = snapshot_frame(snapshots, name)
    labels = labels[series].dropna()
    labels.index = labels.index.to_period("M")
    if not labels.index.is_unique or not labels.isin([0, 1]).all():
        raise ValueError("Expected binary monthly recession labels")
    timestamp = max([label_timestamp, *(stamp for _, stamp in loaded.values())])
    hashes = dict(sorted(hashes.items()))
    input_hash = sha256("\n".join(f"{name}:{body_hashes[name]}" for name in hashes).encode("utf-8")).hexdigest()
    data_hash = sha256("\n".join(f"{name}:{digest}" for name, digest in hashes.items()).encode("utf-8")).hexdigest()
    print("Data source: Yahoo Finance (finance.yahoo.com, yfinance daily data with auto_adjust=False) "
          "and FRED (fred.stlouisfed.org, monthly USREC labels) embedded in config under data.snapshots "
          f"(decompressed sha256 aggregate {data_hash}); "
          "the script does not call yfinance, FRED or any host and reads no data_cache")
    print(f"Input SHA-256: {input_hash}")
    print(f"DATA_SHA256: {data_hash}")
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml", "key": "data.snapshots", "sha256": hashes,
    }))
    return {ticker: frame for ticker, (frame, _) in loaded.items()}, labels, timestamp


def available_treasury(closes, sessions, availability):
    delay = pd.Timedelta(days=availability["treasury_calendar_days"])
    max_age = pd.Timedelta(days=availability["treasury_max_age_days"])
    return closes.dropna().shift(freq=delay).reindex(sessions, method="ffill", tolerance=max_age)


def market_features(prices, universe, availability, model):
    equity = prices[universe["equity_index"]]["Close"]
    if not np.isfinite(equity).all() or (equity <= 0).any():
        raise ValueError("Invalid equity index close")
    yields = {
        term: available_treasury(prices[universe[f"treasury_{term}"]]["Close"],
                                 equity.index, availability)
        for term in ("10y", "5y", "3m")
    }
    log_equity = np.log(equity)
    features = pd.DataFrame({
        "term_10y_3m": yields["10y"] - yields["3m"],
        "term_10y_5y": yields["10y"] - yields["5y"],
        "equity_return": log_equity.diff(model["momentum_sessions"]),
        "negative_equity_vol": -log_equity.diff().rolling(model["volatility_sessions"]).std(),
    })
    monthly = features.groupby(features.index.to_period("M")).tail(1)
    decision_dates = pd.Series(monthly.index, index=monthly.index.to_period("M"))
    monthly.index = decision_dates.index
    monthly = monthly.reindex(pd.period_range(monthly.index[0], monthly.index[-1], freq="M"))
    return monthly, decision_dates, yields["3m"], equity.index


def feature_matrix(monthly, model, continuous):
    if not continuous:
        past = monthly.shift(1).rolling(model["quantile_lookback_months"],
                                        min_periods=model["min_quantile_months"])
        cutoffs = past.quantile(model["lower_tail_quantile"])
        monthly = monthly.lt(cutoffs).astype(float).where(monthly.notna() & cutoffs.notna())
    lags = model["feature_lags_months"]
    return pd.concat([monthly.shift(lag).add_suffix(f"_{lag}m") for lag in lags], axis=1)


def target_schedule(monthly, decision_dates, sessions, labels, dates, config, model,
                    continuous=False):
    universe, availability = config["universe"], config["availability"]
    first = sessions.searchsorted(dates["backtest_start"])
    lag = availability["execution_sessions"]
    if not lag <= first < len(sessions):
        raise ValueError("Need sessions before the first evaluation date and within the backtest")
    first_signal = sessions[first - lag].to_period("M")
    freeze = dates["is_end"]
    features = feature_matrix(monthly.loc[:dates["backtest_end"].to_period("M")], model, continuous)
    target_months = features.index + model["horizon_months"]
    known_months = target_months + availability["recession_label_months"]
    known_dates = known_months.to_timestamp(how="end").normalize()
    target = labels.reindex(target_months).set_axis(features.index)
    complete = features.notna().all(axis=1)
    fit_cutoff = None
    scheduled = {}
    for month, signal_date in decision_dates.loc[first_signal:].items():
        fill_position = sessions.searchsorted(signal_date, side="right") + lag - 1
        if fill_position >= len(sessions) or sessions[fill_position] > dates["backtest_end"]:
            break
        if fill_position < first:
            continue
        if not complete.loc[month]:
            raise ValueError(f"Missing predictors for decision on {signal_date.date()}")

        cutoff = min(signal_date, freeze)
        if fit_cutoff != cutoff:
            eligible = complete & (known_dates <= cutoff)
            y = target.loc[eligible]
            if y.isna().any() or len(y) < model["min_training_months"] or y.nunique() != 2:
                raise ValueError(f"Missing or insufficient matured training labels at {cutoff.date()}")
            model_fit = LogisticRegression(C=model["logit_c"], max_iter=1000, solver="lbfgs")
            if continuous:
                model_fit = make_pipeline(StandardScaler(), model_fit)
            model_fit.fit(features.loc[eligible], y)
            fit_cutoff = cutoff

        probability = float(model_fit.predict_proba(features.loc[[month]])[0, 1])
        target_key = "risk_off" if probability >= model["risk_off_probability"] else "risk_on"
        scheduled[sessions[fill_position]] = universe[target_key]
    if not scheduled:
        raise ValueError("No qualifying fills in the requested backtest window")
    return scheduled


def total_return_prices(daily):
    """Roll forward dividend adjustments using the prior close and today's ex-dividend amount."""
    dividend = daily["Dividends"]
    prior_close = daily["Close"].shift(1)
    if dividend.iloc[0] != 0 or dividend.isna().any():
        raise ValueError("A prior close and a distribution history are required")
    factor = 1 - dividend.div(prior_close).where(dividend.ne(0), 0)
    if not np.isfinite(factor).all() or (factor <= 0).any():
        raise ValueError("Invalid dividend adjustment")
    return daily[["Open", "Close"]].div(factor.cumprod(), axis=0)


def simulate(opens, closes, scheduled, execution):
    commission = execution["commission_bps"] / 10_000
    slippage = execution["slippage_bps"] / 10_000
    friction = commission + slippage
    if commission < 0 or slippage < 0 or friction >= 1:
        raise ValueError("Invalid execution costs")

    previous_value, cash, units = 1.0, 1.0, 0.0
    active = None
    rows = []
    for date, opening_prices, closing_prices in zip(opens.index, opens.to_dict("records"),
                                                     closes.to_dict("records"), strict=True):
        target = scheduled.get(date, active)
        traded, trades, switches = 0.0, 0, 0
        if target != active:
            sold = 0.0
            if active is not None:
                sold = units * opening_prices[active]
                cash += sold * (1 - friction)
                trades += 1
                switches = 1
            opening_value = cash + sold * friction
            bought = cash / (1 + friction)
            units = bought / opening_prices[target]
            cash = 0.0  # The whole budget is spent, including buy-side friction.
            traded = (sold + bought) / opening_value
            trades += 1
            active = target
        closing_value = cash if active is None else cash + units * closing_prices[active]
        rows.append((closing_value / previous_value - 1, traded, trades, switches))
        previous_value = closing_value
    return pd.DataFrame(rows, index=opens.index, columns=["return", "turnover", "trades", "switches"])


def performance(daily_results, risk_free):
    returns = daily_results["return"]
    excess = returns - risk_free.reindex(returns.index)
    if len(returns) < 2 or excess.isna().any():
        raise ValueError("Insufficient returns or risk-free observations")
    compound = (1 + returns).cumprod().to_numpy()
    wealth = np.concatenate(([1.0], compound))
    vol, excess_vol = returns.std(), excess.std()
    annualizer = 252 / len(returns)
    return {
        "cagr": float(wealth[-1] ** annualizer - 1),
        "ann_vol": float(vol * np.sqrt(252)),
        "sharpe": float(returns.mean() / vol * np.sqrt(252)) if vol > 0 else None,
        "sharpe_excess": float(excess.mean() / excess_vol * np.sqrt(252)) if excess_vol > 0 else None,
        "max_drawdown": float((wealth / np.maximum.accumulate(wealth) - 1).min()),
        "total_return": float(wealth[-1] - 1),
        "turnover": float(daily_results["turnover"].sum() * annualizer),
        "n_trades": int(daily_results["trades"].sum()),
    }


def run_robustness(monthly, decisions, sessions, labels, dates, config, opens, closes, risk_free):
    model, robustness = config["model"], config["robustness"]
    trials = [
        (f"lower_tail_quantile={value:g}", {**model, "lower_tail_quantile": value}, False)
        for value in dict.fromkeys(robustness["lower_tail_quantiles"])
        if value != model["lower_tail_quantile"]
    ] + [
        (f"risk_off_probability={value:g}", {**model, "risk_off_probability": value}, False)
        for value in dict.fromkeys(robustness["risk_off_probabilities"])
        if value != model["risk_off_probability"]
    ]
    if robustness["continuous_logit"]:
        trials.append(("continuous_features", model, True))

    end = dates["is_end"]
    is_dates = {**dates, "backtest_end": end}
    is_labels = labels.loc[:end.to_period("M")]
    trial_count = 0
    for name, parameters, continuous in trials:
        scheduled = target_schedule(monthly, decisions.loc[:end.to_period("M")],
                                    sessions[sessions <= end], is_labels, is_dates,
                                    config, parameters, continuous)
        result = simulate(opens.loc[:end], closes.loc[:end], scheduled, config["execution"])
        metrics = performance(result, risk_free)
        print(f"ROBUSTNESS IS {name} " + json.dumps({**metrics, "switches": int(result.switches.sum())},
                                                     allow_nan=False))
        trial_count += 1
    return trial_count


def main():
    config, dates = read_config()
    universe, model, availability = config["universe"], config["model"], config["availability"]
    prices, labels, timestamp = load_inputs(config["data"]["snapshots"], universe, dates)
    monthly, decisions, prior_irx, sessions = market_features(prices, universe, availability, model)
    sessions = sessions[sessions <= dates["backtest_end"]]
    evaluation = sessions[sessions >= dates["backtest_start"]]
    etfs = dict.fromkeys(universe[key] for key in ("risk_on", "risk_off", "benchmark"))
    adjusted = {ticker: total_return_prices(prices[ticker]).reindex(evaluation) for ticker in etfs}
    for ticker, frame in adjusted.items():
        if not np.isfinite(frame).all().all() or (frame <= 0).any().any():
            raise ValueError(f"Missing or invalid ETF opens or closes for {ticker}")
    opens = pd.DataFrame({ticker: frame["Open"] for ticker, frame in adjusted.items()})
    closes = pd.DataFrame({ticker: frame["Close"] for ticker, frame in adjusted.items()})

    # Convert the 91-day bill discount quote to a holding-period proxy over elapsed calendar days.
    elapsed = sessions.to_series().diff().dt.days.reindex(evaluation)
    discount = prior_irx.reindex(evaluation) / 100
    risk_free = (1 - discount * 91 / 360) ** (-elapsed / 91) - 1
    if not np.isfinite(risk_free).all():
        raise ValueError("Missing prior Treasury bill quote or session before the first fill")

    print(f"DATA_FETCHED_AT: {timestamp}")
    print("PRICE_ADJUSTMENT: yfinance split-normalized ETF OHLC with forward ex-dividend adjustment")
    with threadpool_limits(limits=1, user_api="blas"):
        trials = run_robustness(monthly, decisions, sessions, labels, dates, config, opens, closes, risk_free)
        scheduled = target_schedule(monthly, decisions, sessions, labels, dates, config, model)
    result = simulate(opens, closes, scheduled, config["execution"])
    benchmark = simulate(opens, closes, {evaluation[0]: universe["benchmark"]}, config["execution"])
    split = dates["is_end"]

    def periods(daily):
        return {"is": performance(daily.loc[:split], risk_free),
                "oos": performance(daily.loc[daily.index > split], risk_free),
                "full": performance(daily, risk_free)}

    strategy_periods = periods(result)
    bench_periods = periods(benchmark)
    print(f"SWITCHES: IS={result.loc[:split, 'switches'].sum()} "
          f"OOS={result.loc[result.index > split, 'switches'].sum()} FULL={result.switches.sum()}")
    if result.switches.sum() == 0:
        raise RuntimeError("The default specification produced no ETF rotations")
    for period, metrics in strategy_periods.items():
        print(f"{period.upper()} " + json.dumps(metrics, allow_nan=False))
        print(f"BENCHMARK {period.upper()} " + json.dumps(bench_periods[period], allow_nan=False))
    print(f"PARAM_COMBOS_TRIED: {trials + 1}")
    output = {
        "strategy": config["strategy"],
        "data_range": {"start": str(evaluation[0].date()), "end": str(evaluation[-1].date())},
        **strategy_periods,
        "benchmark": {"name": f"{universe['benchmark']} buy and hold",
                      **bench_periods["full"], **bench_periods},
    }
    print("RESULTS_JSON: " + json.dumps(output, allow_nan=False))


if __name__ == "__main__":
    main()
